def escape(kw, params_acc, vars, env) when is_list(kw) do
  Enum.reduce(kw, {[], []}, fn
    {:partition_by, fields}, {compile, runtime} ->
      {fields, params_acc} = escape_compile({:partition_by, fields}, params_acc, vars, env)
      {[{:partition_by, fields} | compile], runtime}

    {:order_by, fields}, {compile, runtime} ->
      {fields, params_acc} = escape_compile({:order_by, fields}, params_acc, vars, env)
      {[{:order_by, fields} | compile], runtime}

    {:frame, frame_clause}, {compile, runtime} ->
      {frame_clause, params_acc} = escape_compile({:frame, frame_clause}, params_acc, vars, env)
      {[{:frame, frame_clause} | compile], runtime}
  end)
end

def escape(kw, params_acc, vars, env) when is_list(kw) do
