  |> Enum.reduce({[], [], params_acc}, fn
    {key, value}, {compile, runtime, params_acc} when key in [:partition_by, :order_by, :frame] ->
      {escaped_value, new_params_acc} = escape_compile({key, value}, params_acc, vars, env)
      {[escaped_value | compile], runtime, new_params_acc}

    {key, value}, {compile, runtime, params_acc} ->
      {compile, [{key, value} | runtime], params_acc}
  end)
  |> case do
    {compile, [], params_acc} ->
      {Enum.reverse(compile), [], params_acc}

    {compile, runtime, params_acc} ->
      {Enum.reverse(compile), Enum.reverse(runtime), params_acc}
  end
end

